{\"t\":\"electronic signature has the same legal effect as a handwritten signature.\",\"x\":56,\"y\":893,\"w\":384.39,\"h\":16,\"bl\":906,\"s\":12,\"c\":\"#334155\"},{\"t\":\"SIGNATURES\",\"x\":56,\"y\":932,\"w\":67.81,\"h\":16,\"bl\":945,\"s\":12,\"c\":\"#334155\"},{\"t\":\"By signing below, the Company and the Counterparty agree to the terms of this Agreement.\",\"x\":56,\"y\":951.5,\"w\":485.72,\"h\":16,\"bl\":964.5,\"s\":12,\"c\":\"#334155\"}],\"rects\":[{\"x\":56,\"y\":994,\"w\":680,\"h\":1,\"c\":\"#e2e8f0\",\"f\":1},{\"x\":56,\"y\":114.5,\"w\":680,\"h\":1,\"c\":\"#e2e8f0\",\"f\":1}],\"images\":[]},{\"height\":1121,\"texts\":[{\"t\":\"General Business Agreement.pdf\",\"x\":56,\"y\":58,\"w\":276.86,\"h\":24,\"bl\":77,\"s\":18,\"c\":\"#0f172a\",\"b\":1},{\"t\":\"Execution & Signatures • Page\",\"x\":56,\"y\":87,\"w\":175.39,\"h\":13,\"bl\":97,\"s\":11,\"c\":\"#64748b\",\"m\":1},{\"t\":\"2\",\"x\":237.44,\"y\":87,\"w\":6.06,\"h\":13,\"bl\":97,\"s\":11,\"c\":\"#64748b\",\"m\":1},{\"t\":\"of\",\"x\":249.55,\"y\":87,\"w\":12.11,\"h\":13,\"bl\":97,\"s\":11,\"c\":\"#64748b\",\"m\":1},{\"t\":\"2\",\"x\":267.7,\"y\":87,\"w\":6.06,\"h\":13,\"bl\":97,\"s\":11,\"c\":\"#64748b\",\"m\":1},{\"t\":\"IN WITNESS WHEREOF, the parties hereto have executed this Agreement by affixing their digital signatures and requested\",\"x\":56,\"y\":115.5,\"w\":644.09,\"h\":16,\"bl\":128.5,\"s\":12,\"c\":\"#475569\"},{\"t\":\"verification fields below.\",\"x\":56,\"y\":135,\"w\":127.33,\"h\":16,\"bl\":148,\"s\":12,\"c\":\"#475569\"}],\"rects\":[{\"x\":56,\"y\":169.5,\"w\":680,\"h\":1,\"c\":\"#e2e8f0\",\"f\":1}],\"images\":[]}]}');
